fn solve(n: i8) -> i8 {
    // For positive n, integer division n/2 is floor(n/2).
    // Closed‐form:
    //   if n is even:  S =  n/2
    //   if n is odd:   S = (n/2) - n
    if n % 2 == 0 {
        n / 2
    } else {
        n / 2 - n
    }
}

